import { getDefaultKeyAlg, getJwksAdapter } from "./adapter.mjs";
import { getCurrentAuthEndpointContext } from "@better-auth/core/context";
import { base64 } from "@better-auth/utils/base64";
import { importJWK, jwtVerify } from "jose";
//#region src/plugins/jwt/verify.ts
/**
* Verify a JWT token using the JWKS public keys
* Returns the payload if valid, null otherwise
*/
async function verifyJWT(token, options) {
	const ctx = getCurrentAuthEndpointContext();
	try {
		const parts = token.split(".");
		if (parts.length !== 3) return null;
		const headerStr = new TextDecoder().decode(base64.decode(parts[0]));
		const kid = JSON.parse(headerStr).kid;
		if (!kid) {
			ctx.context.logger.debug("JWT missing kid in header");
			return null;
		}
		const keys = await getJwksAdapter(ctx.context.adapter, options).getAllKeys(ctx);
		if (!keys || keys.length === 0) {
			ctx.context.logger.debug("No JWKS keys available");
			return null;
		}
		const key = keys.find((k) => k.id === kid);
		if (!key) {
			ctx.context.logger.debug(`No JWKS key found for kid: ${kid}`);
			return null;
		}
		const publicKey = JSON.parse(key.publicKey);
		const alg = key.alg ?? getDefaultKeyAlg(options);
		const cryptoKey = await importJWK(publicKey, alg);
		const baseURLOrigin = typeof ctx.context.options.baseURL === "string" ? ctx.context.options.baseURL : void 0;
		const issuer = options?.jwt?.issuer ?? baseURLOrigin;
		const audience = options?.jwt?.audience ?? baseURLOrigin;
		if (!issuer || !audience) ctx.context.logger.warn("[better-auth] The JWT plugin is verifying a JWT without checking its issuer or audience because no base URL was resolved for this call. Set `baseURL`, or `jwt.issuer` and `jwt.audience` in the JWT plugin options.");
		const { payload } = await jwtVerify(token, cryptoKey, {
			issuer,
			audience,
			algorithms: [alg]
		});
		if (!payload.sub || !payload.aud) return null;
		return payload;
	} catch (error) {
		ctx.context.logger.debug("JWT verification failed", error);
		return null;
	}
}
